from lib import *
LESSON = 'មុំ'
D_ = '^\\circ'
def dms(total_s):
    d, r = divmod(total_s, 3600); m, s = divmod(r, 60)
    return d, m, s
def DMS(d, m=0, s=0):
    out = f'{d}^\\circ'
    if m or s: out += f'\\ {m}\\prime'
    if s: out += f'\\ {s}\\prime\\prime'
    return out
def tot(d, m, s): return d * 3600 + m * 60 + s
